@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<double> logDays, double minGap) {
  var lo = 0;
  var hi = logDays.length;

  while (lo < hi) {
    final mid = (lo + hi) >> 1;
    if (logDays[mid] < minGap) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }

  if (lo < logDays.length) {
    return logDays[lo];
  }

  return -1.0;
}

@pragma('vm:never-inline')
