int fn0(String s, int threshold) {
  int result = 0;
  int i = 0;
  int n = s.length;
  while (i < n) {
    int start = i;
    while (i < n) {
      int code = s.codeUnitAt(i);
      if (code >= 0x30 && code <= 0x39) {
        i++;
      } else {
        break;
      }
    }
    int number = int.parse(s.substring(start, i));
    int letterCode = s.codeUnitAt(i) - 0x41 + 1; // 'A' -> 1, 'B' -> 2, ...
    i++;
    if (letterCode > threshold) {
      result += number * letterCode;
    }
  }
  return result;
}
